//! The tag entity of the `tags` resource, generated by
//! `forge generate scaffold`. Business rules only: no HTTP, SQL or runtime
//! types, so the rules are unit-testable and shared by every adapter.

use std::fmt;

use forge::core::{Id, Version};

/// Identifier of a [`Tag`]: a typed UUIDv7 generated in Rust, never by
/// the database.
pub type TagId = Id<Tag>;

/// Maximum length, in characters, of a `string` field.
pub const STRING_MAX_CHARS: usize = 255;

/// The values a tag is made of. [`Tag`] only holds values that pass
/// [`TagAttributes::validate`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TagAttributes {
    pub label: String,
    pub active: Option<bool>,
}

impl TagAttributes {
    /// Checks every business rule and reports all violations at once.
    pub fn validate(&self) -> Result<(), TagValidationErrors> {
        let mut errors = TagValidationErrors::default();
        check_text(&mut errors, TagField::Label, &self.label, STRING_MAX_CHARS);
        errors.into_result()
    }
}

/// Text must not be blank and must fit `max` characters.
fn check_text(errors: &mut TagValidationErrors, field: TagField, value: &str, max: usize) {
    if value.trim().is_empty() {
        errors.push(field, TagViolation::Blank);
    } else if value.chars().count() > max {
        errors.push(field, TagViolation::TooLong { max });
    }
}

/// A tag: an identity, an optimistic-locking version and valid
/// attributes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Tag {
    id: TagId,
    version: Version,
    attributes: TagAttributes,
}

impl Tag {
    /// A new tag with a fresh UUIDv7 and the initial version.
    pub fn new(attributes: TagAttributes) -> Result<Self, TagValidationErrors> {
        Self::restore(TagId::new(), Version::INITIAL, attributes)
    }

    /// A tag read from storage or about to replace a stored one,
    /// validated like a new one.
    pub fn restore(
        id: TagId,
        version: Version,
        attributes: TagAttributes,
    ) -> Result<Self, TagValidationErrors> {
        attributes.validate()?;
        Ok(Self {
            id,
            version,
            attributes,
        })
    }

    /// The same tag at `version`, after storage accepted a change.
    #[must_use]
    pub fn with_version(self, version: Version) -> Self {
        Self { version, ..self }
    }

    #[must_use]
    pub fn id(&self) -> TagId {
        self.id
    }

    /// The optimistic-locking version: an update or delete must present it.
    #[must_use]
    pub fn version(&self) -> Version {
        self.version
    }

    #[must_use]
    pub fn attributes(&self) -> &TagAttributes {
        &self.attributes
    }

    #[must_use]
    pub fn label(&self) -> &str {
        &self.attributes.label
    }

    #[must_use]
    pub fn active(&self) -> Option<bool> {
        self.attributes.active
    }
}

/// A field of [`TagAttributes`].
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TagField {
    Label,
    Active,
}

impl TagField {
    /// The field's name in forms and storage.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Label => "label",
            Self::Active => "active",
        }
    }
}

/// A broken business rule.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TagViolation {
    /// The value is empty or only whitespace.
    Blank,
    /// The value has more than `max` characters.
    TooLong { max: usize },
}

impl fmt::Display for TagViolation {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Blank => formatter.write_str("can't be blank"),
            Self::TooLong { max } => write!(formatter, "is too long (at most {max} characters)"),
        }
    }
}

/// Every broken rule of a tag, in field order.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct TagValidationErrors {
    violations: Vec<(TagField, TagViolation)>,
}

impl TagValidationErrors {
    /// Records that `field` breaks a rule.
    pub fn push(&mut self, field: TagField, violation: TagViolation) {
        self.violations.push((field, violation));
    }

    /// Whether no rule is broken.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.violations.is_empty()
    }

    /// The first violation of `field`.
    #[must_use]
    pub fn get(&self, field: TagField) -> Option<TagViolation> {
        self.violations
            .iter()
            .find(|(candidate, _)| *candidate == field)
            .map(|(_, violation)| *violation)
    }

    /// Every violation in the order it was found.
    pub fn iter(&self) -> impl Iterator<Item = (TagField, TagViolation)> + '_ {
        self.violations.iter().copied()
    }

    /// `Ok` when no rule is broken.
    pub fn into_result(self) -> Result<(), Self> {
        if self.is_empty() { Ok(()) } else { Err(self) }
    }
}

impl fmt::Display for TagValidationErrors {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("tag is invalid")?;
        for (index, (field, violation)) in self.violations.iter().enumerate() {
            let separator = if index == 0 { ": " } else { ", " };
            write!(formatter, "{separator}{} {violation}", field.name())?;
        }
        Ok(())
    }
}

impl std::error::Error for TagValidationErrors {}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> TagAttributes {
        TagAttributes {
            label: "Example label".to_owned(),
            active: Some(true),
        }
    }

    #[test]
    fn new_tags_get_a_uuidv7_and_the_initial_version() {
        let created = Tag::new(valid());

        let Ok(entity) = created else {
            panic!("valid attributes must be accepted: {created:?}");
        };
        assert_eq!(entity.id().as_uuid().get_version_num(), 7);
        assert_eq!(entity.version(), Version::INITIAL);
        assert_eq!(entity.attributes(), &valid());
    }

    #[test]
    fn blank_and_too_long_text_is_rejected_with_every_violation() {
        let mut attributes = valid();
        attributes.label = "x".repeat(STRING_MAX_CHARS + 1);

        let Err(errors) = Tag::new(attributes) else {
            panic!("blank and too long values must be rejected");
        };
        assert_eq!(
            errors.get(TagField::Label),
            Some(TagViolation::TooLong {
                max: STRING_MAX_CHARS
            })
        );
    }

    #[test]
    fn restore_validates_and_with_version_keeps_the_identity() -> Result<(), TagValidationErrors> {
        let entity = Tag::new(valid())?;
        let restored = Tag::restore(entity.id(), entity.version(), valid())?;
        assert_eq!(restored, entity);

        let Ok(next) = Version::INITIAL.next() else {
            panic!("version 2 exists");
        };
        let moved = restored.with_version(next);
        assert_eq!(moved.id(), entity.id());
        assert_eq!(moved.version().get(), 2);
        Ok(())
    }
}
